from datetime import datetime

# Re-parse with full analysis
entries = [
    ("2023-01-30", "An arc of colored light in the sky caused by refraction of the sun's rays by rain is never an appropriate definition of rainbow in any context."),
    ("2022-04-25", "Not a single shopping may commonly be searching for or buying goods or services."),
    ("2023-09-01", "No support is the financial means whereby one lives."),
    ("2022-07-08", "Suffering never refers to feelings of mental or physical pain."),
    ("2022-02-27", "The soft tissue of the body of a vertebrate: mainly muscle tissue and fat is not an appropriate definition of flesh."),
    ("2022-08-19", "Manual commonly stands for a female human offspring."),
    ("2024-06-05", "No pair may be two people considered as a unit."),
    ("2023-03-26", "In certain contexts someone who is under suspicion may be an appropriate definition of suspect."),
    ("2023-07-16", "No hypothesis may be a message expressing an opinion based on incomplete evidence."),
    ("2023-01-28", "The mother of your father or mother may be an appropriate definition of vat in certain contexts."),
    ("2023-08-08", "An outward appearance is an appropriate definition of joke."),
    ("2025-04-21", "Sleeve never stands for the part of a garment that is attached at the armhole and that provides a cloth covering for the arm."),
]

# Determine labels (True if claim is factually correct, False otherwise)
# These are all negated claims - check if the negation is correct
labels = []
for date_str, text in entries:
    date = datetime.strptime(date_str, "%Y-%m-%d")

    # Analyze each claim
    if "never an appropriate definition of rainbow" in text:
        label = False  # That IS the definition of rainbow
    elif "Not a single shopping may commonly be searching for or buying goods" in text:
        label = False  # Shopping IS commonly that
    elif "No support is the financial means" in text:
        label = False  # Support CAN BE financial means
    elif "Suffering never refers to feelings of mental or physical pain" in text:
        label = False  # Suffering DOES refer to pain
    elif "is not an appropriate definition of flesh" in text:
        label = False  # That IS the definition of flesh
    elif "Manual commonly stands for a female human offspring" in text:
        label = False  # Manual means by hand/handbook, not daughter
    elif "No pair may be two people considered as a unit" in text:
        label = False  # A pair CAN BE two people as a unit
    elif "someone who is under suspicion may be an appropriate definition of suspect" in text:
        label = True   # A suspect IS someone under suspicion
    elif "No hypothesis may be a message expressing an opinion based on incomplete evidence" in text:
        label = False  # A hypothesis IS that
    elif "mother of your father or mother may be an appropriate definition of vat" in text:
        label = False  # That's grandmother, not vat
    elif "outward appearance is an appropriate definition of joke" in text:
        label = False  # Outward appearance is not a joke
    elif "Sleeve never stands for the part of a garment" in text:
        label = False  # Sleeve DOES stand for that
    else:
        label = "UNKNOWN"

    labels.append((date_str, date, label, text[:50]))

# Print all with labels
for date_str, date, label, text in labels:
    print(f"{date_str} | {label} | {text}...")
